commands.command:
set -eu
cat > /etc/nginx/sites-available/help-site <<'ANTRIEB_NGINX'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;

    root /srv/legacy2/permanent-url-migration;

    location = /status.txt {
        default_type text/plain;
        try_files /status.txt =404;
    }

    location = /manual {
        return 301 /help/$is_args$args;
    }

    location ~ ^/manual/(.*)$ {
        return 301 /help/$1$is_args$args;
    }

    location = /help {
        return 301 /help/$is_args$args;
    }

    location /help/ {
        try_files $uri $uri/ =404;
    }

    location / {
        return 404;
    }
}
ANTRIEB_NGINX
ln -sfn /etc/nginx/sites-available/help-site /etc/nginx/sites-enabled/help-site
rm -f /etc/nginx/sites-enabled/default
nginx -t
systemctl restart nginx
systemctl enable nginx
systemctl is-active nginx
systemctl is-enabled nginx

